package com.sentinelai.incidents.api;
import com.sentinelai.incidents.domain.*; import com.sentinelai.incidents.infrastructure.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*; import org.springframework.data.domain.PageRequest; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/incidents") public class IncidentController {
 private final IncidentRepository incidents; private final IncidentEvidenceRepository evidence; private final IncidentCommentRepository comments; private final IncidentTagRepository tags;
 public IncidentController(IncidentRepository incidents,IncidentEvidenceRepository evidence,IncidentCommentRepository comments,IncidentTagRepository tags){this.incidents=incidents;this.evidence=evidence;this.comments=comments;this.tags=tags;}
 @GetMapping public Map<String,Object> list(@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,Authentication auth){var tenant=tenant(auth);var result=(status.isBlank()?incidents.findByTenantIdAndTitleContainingIgnoreCase(tenant,search,PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)))):incidents.findByTenantIdAndTitleContainingIgnoreCaseAndStatus(tenant,search,status,PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)))));return Map.of("items",result.getContent(),"page",result.getNumber(),"totalPages",result.getTotalPages(),"totalItems",result.getTotalElements());}
 @PostMapping public ResponseEntity<Incident> create(@RequestBody CreateRequest request,Authentication auth){var incident=new Incident(UUID.randomUUID(),tenant(auth),request.title(),request.severity(),request.assignee());return ResponseEntity.status(HttpStatus.CREATED).body(incidents.save(incident));}
 @PostMapping("/{id}/evidence") public Map<String,String> attach(@PathVariable UUID id,@RequestBody EvidenceRequest request,Authentication auth){var tenant=tenant(auth);var incident=incidents.findById(id).filter(i->tenant.equals(i.getTenantId())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var hash=sha256(request.eventRef()+"|"+incident.getId());evidence.save(new IncidentEvidence(UUID.randomUUID(),id,tenant,request.eventRef(),hash));return Map.of("eventRef",request.eventRef(),"sha256",hash,"immutable","true");}
 @GetMapping("/summary") public Map<String,Object> summary(Authentication auth){var tenant=tenant(auth);return Map.of("open",incidents.countByTenantIdAndStatus(tenant,"OPEN"),"investigating",incidents.countByTenantIdAndStatus(tenant,"INVESTIGATING"),"resolved",incidents.countByTenantIdAndStatus(tenant,"RESOLVED"));}
 @PostMapping("/{id}/comments") public Map<String,String> comment(@PathVariable UUID id,@RequestBody CommentRequest request,Authentication auth){String tenant=tenant(auth);check(id,tenant);comments.save(new IncidentComment(UUID.randomUUID(),id,tenant,auth.getName(),request.body()));return Map.of("status","created");}
 @PostMapping("/{id}/tags") public Map<String,String> tag(@PathVariable UUID id,@RequestBody TagRequest request,Authentication auth){String tenant=tenant(auth);check(id,tenant);tags.save(new IncidentTag(id,tenant,request.tag()));return Map.of("status","created","tag",request.tag());}
 private void check(UUID id,String tenant){incidents.findById(id).filter(i->tenant.equals(i.getTenantId())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 private String tenant(Authentication auth){if(auth instanceof JwtAuthenticationToken jwt){var t=jwt.getToken().getClaimAsString("tenant_id");if(t!=null&&!t.isBlank())return t;}throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant missing");}
 private String sha256(String value){try{var bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(bytes);}catch(Exception e){throw new IllegalStateException(e);}}
 public record CreateRequest(String title,String severity,String assignee){} public record EvidenceRequest(String eventRef){} public record CommentRequest(String body){} public record TagRequest(String tag){}
}


